Here is a solution that uses a for loop to iterate through the array and check each element:

```javascript
function findElement(arr, element) {
  for (var i = 0; i < arr.length; i++) {
    if (arr[i] === element) {
      return i;
    }
  }
  return -1;
}

var arr = [1, 2, 3, 4, "apple", "banana", "orange"];
var element = "banana";
var index = findElement(arr, element);
console.log(index); // Output: 5
```

