```python
from bs4 import BeautifulSoup

def parse_html(html_code):
    soup = BeautifulSoup(html_code, 'html.parser')
    return parse_element(soup)

def parse_element(element):
    if element.string:
        return element.string.strip()

    result = {}
    for child in element.children:
        if child.name is None:
            continue

        if child.name in result:
            if not isinstance(result[child.name], list):
                result[child.name] = [result[child.name]]
            result[child.name].append(parse_element(child))
        else:
            result[child.name] = parse_element(child)

    for attr_name, attr_value in element.attrs.items():
        result['@'+attr_name] = attr_value

    return result
```

