// Function to check if a number is prime
int isPrime(int n) {
    if (n <= 1) return 0;
    if (n <= 3) return 1;
    if (n % 2 == 0 || n % 3 == 0) return 0;
    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return 0;
    }
    return 1;
}

// Function to generate a random prime number between 1000 and 5000
int generateRandomPrime() {
    int prime;
    do {
        prime = rand() % 4001 + 1000;
    } while (!isPrime(prime));
    return prime;
}

// Function to encrypt a string using the custom encryption algorithm
void encryptString(const char *input, char *output) {
    int len = strlen(input);
    int prime = generateRandomPrime();
    srand(time(NULL));

    for (int i = 0; i < len; i++) {
        int ascii = (int)input[i];
        int encrypted = (ascii + prime) * (i + 1);
        sprintf(output + strlen(output), "%X", encrypted);
    }
}

