            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static int largestPrimeLessThan(int number) {
        if (number < 2) {
            return -1; // Return -1 for invalid input
        }
        if (number == 2) {
            return 2; // Return 2 for special case
        }
        number = number - 1; // Decrement number by 1 to find smaller prime
        while (number >= 2) {
            if (isPrime(number)) {
                return number; // Return the largest prime found
            }
            number--;
        }
        return -1; // Return -1 if no prime number found
    }

    public static void main(String[] args) {
        int number = 50;
        int largestPrime = largestPrimeLessThan(number);
        System.out.println("Largest prime less than " + number + ": " + largestPrime);
    }
}
