public class FactorialCalculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        int number = getValidNumber(scanner);

        System.out.println("1. Calculate factorial using recursion");
        System.out.println("2. Calculate factorial using iteration");

        int choice = getValidChoice(scanner);

        if (choice == 1) {
            long startTime = System.nanoTime();
            long factorial = calculateFactorialRecursively(number);
            long endTime = System.nanoTime();

            System.out.println("Factorial of " + number + " using recursion: " + factorial);
            System.out.println("Time taken: " + (endTime - startTime) + " nanoseconds");
        } else {
            long startTime = System.nanoTime();
            long factorial = calculateFactorialIteratively(number);
            long endTime = System.nanoTime();

            System.out.println("Factorial of " + number + " using iteration: " + factorial);
            System.out.println("Time taken: " + (endTime - startTime) + " nanoseconds");
        }

        scanner.close();
    }

    private static int getValidNumber(Scanner scanner) {
        System.out.print("Enter a non-negative integer: ");
        int number = scanner.nextInt();

        while (number < 0) {
            System.out.print("Invalid input. Enter a non-negative integer: ");
            number = scanner.nextInt();
        }

        return number;
    }

    private static int getValidChoice(Scanner scanner) {
        System.out.print("Enter your choice (1 or 2): ");
        int choice = scanner.nextInt();

        while (choice != 1 && choice != 2) {
            System.out.print("Invalid choice. Enter your choice (1 or 2): ");
            choice = scanner.nextInt();
        }

        return choice;
    }

    private static long calculateFactorialRecursively(int number) {
        if (number == 0 || number == 1) {
            return 1;
        }

        return number * calculateFactorialRecursively(number - 1);
    }

    private static long calculateFactorialIteratively(int number) {
        long factorial = 1;

        for (int i = 1; i <= number; i++) {
            factorial *= i;
        }

        return factorial;
    }
}

