    // Generate an array of prime numbers with unique values within a specified range
    public static int[] generatePrimeArray(int size, int lowerBound, int upperBound) {
        Random random = new Random();
        int[] primeArray = new int[size];
        int count = 0;

        while (count < size) {
            int randomNum = random.nextInt(upperBound - lowerBound + 1) + lowerBound;
            if (isPrime(randomNum) && !contains(primeArray, count, randomNum)) {
                primeArray[count] = randomNum;
                count++;
            }
        }
        return primeArray;
    }

    // Check if a number is prime
    public static boolean isPrime(int num) {
        if (num < 2) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }

    // Check if an array contains a specific value within a given count
    public static boolean contains(int[] array, int count, int value) {
        for (int i = 0; i < count; i++) {
            if (array[i] == value) {
