bool isPrime(int num) {
    if(num < 2) return false;
    for(int i = 2; i <= num/2; i++) {
        if(num % i == 0)
            return false;
    }
    return true;
}

bool isUnique(char char1, char char2) {
    if(char1 == char2 || (char1 >= 'a' && char1 <= 'z') || (char2 >= 'a' && char2 <= 'z'))
        return false;
    return true;
}

void printDiamond(int size, char fillChar, char borderChar) {
    int space = size/2;
    int star = 1;
    bool increasing = true;

    for(int i = 0; i < size; i++) {
        for(int j = 0; j < space; j++) {
            printf(" ");
        }

        for(int j = 0; j < star; j++) {
            if(j == 0 || j == star - 1 || i == 0 || i == size - 1) {
                printf("%c", borderChar);
            } else {
                printf("%c", fillChar);
            }
        }

        printf("\n");

        if(space == 0) {
            increasing = false;
        }

        if(increasing) {
            space--;
            star += 2;
        } else {
            space++;
            star -= 2;
        }
    }
}

int main() {
