    char fillChar, borderChar;

    printf("Enter the size of the diamond (odd prime number between 13 and 37): ");
    scanf("%d", &size);

    if(size < 13 || size > 37 || size % 2 == 0 || !isPrime(size)) {
        printf("Invalid size! Please enter an odd prime number between 13 and 37.\n");
