function capitalizeAndRemoveSpaces(input) {
  let result = '';

  let capitalizeNext = true; // Flag to track when to capitalize the next letter

  for (let i = 0; i < input.length; i++) {
    const char = input[i];

    if (char === ' ') {
      capitalizeNext = true; // Reset the flag when encountering a space
    } else {
      if (capitalizeNext) {
        result += char.toUpperCase();
        capitalizeNext = false;
      } else {
        result += char.toLowerCase();
      }
    }
  }

  return result;
}
