```php
<?php

function isPrime($num)
{
    if ($num <= 1) {
        return false;
    }

    for ($i = 2; $i <= sqrt($num); $i++) {
        if ($num % $i === 0) {
            return false;
        }
    }

    return true;
}

$primes = [];
$count = 0;
$prevPrime = 0;

while ($count < 1000) {
    $randomNumber = mt_rand($prevPrime + 1, 10000);

    if (isPrime($randomNumber)) {
        $primes[] = $randomNumber;
        $prevPrime = $randomNumber;
        $count++;
    }
}

print_r($primes);

?>
